\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}

\title{Weak-Acid Titration Curves: Laboratory Report}
\author{Analytical Chemistry Teaching Lab}
\date{April 2026}

\begin{document}
\maketitle

\section{Procedure}
Three unknown monoprotic weak acids (A, B, C) were titrated
with standardised 0.0985~M NaOH at 25~$^\circ$C. Each sample
was dissolved in 100~mL of deionised water, and the titrant
was added in 2~mL portions, then in 1~mL portions near the
equivalence point. The pH was read after each addition once
the drift fell below 0.02 units per minute. The electrode was
recalibrated with pH 4.00 and pH 7.00 buffers between runs.

\section{Recorded data}
Table~\ref{tab:readings} reproduces the bench notebook
readings at selected titrant volumes; the complete series is
plotted in Figure~\ref{fig:curves}.

\begin{table}[ht]
\centering
\begin{tabular}{lccc}
\toprule
NaOH volume (mL) & acid A pH & acid B pH & acid C pH \\
\midrule
0.0  & 2.87 & 3.05 & 2.62 \\
10.0 & 3.77 & 3.88 & 3.61 \\
20.0 & 4.88 & 4.92 & 4.80 \\
22.0 & 5.41 & 5.40 & 5.38 \\
23.0 & 6.14 & 5.83 & 5.95 \\
24.0 & 10.35 & 9.87 & 10.02 \\
26.0 & 11.25 & 11.12 & 11.18 \\
30.0 & 11.72 & 11.65 & 11.69 \\
\bottomrule
\end{tabular}
\caption{Notebook readings at selected volumes.}
\label{tab:readings}
\end{table}

\begin{figure}[ht]
\centering
\begin{tikzpicture}
\begin{axis}[
    width=0.85\textwidth,
    xlabel={NaOH volume (mL)},
    ylabel={pH},
    legend pos=south east,
    grid=both]
\addplot[mark=*, color=blue] coordinates {(0,2.87) (2,3.12) (4,3.31) (6,3.47) (8,3.62) (10,3.77) (12,3.93) (14,4.10) (16,4.30) (18,4.55) (20,4.88) (21,5.10) (22,5.41) (23,61.4) (24,10.35) (25,10.92) (26,11.25) (28,11.55) (30,11.72)};
\addlegendentry{acid A}
\addplot[mark=square*, color=red] coordinates {(0,3.05) (2,3.28) (4,3.45) (6,3.60) (8,3.74) (10,3.88) (12,4.03) (14,4.19) (16,4.38) (18,4.61) (20,4.92) (21,5.12) (22,5.40) (23,5.83) (24,9.87) (25,10.71) (26,11.12) (28,11.46) (30,11.65)};
\addlegendentry{acid B}
\addplot[mark=triangle*, color=teal] coordinates {(0,2.62) (2,2.90) (4,3.11) (6,3.29) (8,3.45) (10,3.61) (12,3.78) (14,3.97) (16,4.18) (18,4.45) (20,4.80) (21,5.05) (22,5.38) (23,5.95) (24,10.02) (25,10.80) (26,11.18) (28,11.50) (30,11.69)};
\addlegendentry{acid C}
\end{axis}
\end{tikzpicture}
\caption{Titration curves for the three unknowns.}
\label{fig:curves}
\end{figure}

\section{Discussion}
The equivalence volumes cluster near 23.5~mL for all three
samples, which is consistent with the nominal 0.25~g masses
weighed out at the bench. Half-equivalence readings place the
p$K_a$ of acid A near 4.9, acid B near 4.9, and acid C near
4.8, so the three unknowns are likely close structural
relatives. Acid A shows the shallowest buffer region, which
matches its slightly stronger acidity.

\section{Sources of error}
The dominant uncertainty is the electrode settling time near
the equivalence point, where one titrant portion can swing
the reading by more than three pH units. Temperature drift
was below 0.5~$^\circ$C over each run and was not corrected
for. Transcription between the bench notebook and this
report was double-checked except where noted during review.

\section{Conclusion}
All three samples behave as monoprotic weak acids with
comparable molecular weights and closely spaced p$K_a$
values. Identification against the candidate list will use
the half-equivalence readings reported above.
\end{document}

